package edu.college.employee.web;
import com.fasterxml.jackson.databind.JsonNode;import edu.college.employee.dsa.*;import edu.college.employee.model.*;import edu.college.employee.service.App;import edu.college.employee.service.AppData;import java.io.IOException;import java.math.BigDecimal;import java.time.*;import java.util.*;
public final class ApiController {
 public void get(HttpRequest q,HttpResponse s)throws IOException{String p=path(q);Web.UserSession u=Web.user(q);AppData r=App.repo();try{
  if(p.equals("/activity/stack")){hr(u);Web.send(s,200,Map.of("activities",r.activity(),"size",r.activityCount(),"empty",r.activityIsEmpty()));return;}if(specialGet(p,u,r,s))return;if(p.startsWith("/employees/")){hr(u);String id=p.substring("/employees/".length());if(id.isBlank()||id.contains("/"))throw new NoSuchElementException();Employee e=Optional.ofNullable(r.searchEmployeeInList(id)).orElseThrow();Web.send(s,200,e);return;}switch(p){case "/employees"->{hr(u);Map<String,String> sort=employeeSortQuery(q.getQuery());String field=sort.getOrDefault("sortBy","id");boolean ascending=switch(sort.getOrDefault("direction","asc")){case "asc"->true;case "desc"->false;default->throw new IllegalArgumentException("Sort direction must be asc or desc.");};String search=sort.getOrDefault("search","");String status=sort.getOrDefault("status","");if(search.length()>1000)throw new IllegalArgumentException("Search text is too long.");if(!status.isEmpty()&&!Set.of("ACTIVE","ON_LEAVE","INACTIVE").contains(status))throw new IllegalArgumentException("Unsupported employee status.");List<Employee> matches=searchEmployees(r.employees(),search,status,sort.getOrDefault("searchAlgorithm","linear").toLowerCase(Locale.ROOT),r::searchEmployeeInBst);Web.send(s,200,EmployeeAlgorithms.mergeSort(matches,field,ascending));}case "/dashboard"->{if(privileged(u)){var es=r.employees();var status=new TreeMap<String,Long>();var dept=new TreeMap<String,Long>();r.departments().forEach(d->dept.put(d,0L));es.forEach(e->{status.merge(e.status(),1L,Long::sum);dept.merge(e.department(),1L,Long::sum);});Web.send(s,200,Map.of("totalEmployees",es.size(),"totalHRAccounts",r.users().stream().filter(a->a.role().equals("HR")).count(),"departments",dept,"statuses",status,"pendingRequests",r.requests().stream().filter(x->x.status().equals("PENDING")).count(),"pendingRegistrationRequests",r.registrationRequests().stream().filter(x->x.status().equals("PENDING")).count(),"recentActivity",r.activity().stream().limit(8).toList()));}else{var own=owned(r,u);Web.send(s,200,Map.of("employee",own,"requests",r.requests().stream().filter(x->x.employeeId().equals(own.id())).toList()));}}case "/requests"->{var all=r.requests();Web.send(s,200,privileged(u)?all:all.stream().filter(x->x.employeeId().equals(u.employeeId())).toList());}case "/activity"->{hr(u);Web.send(s,200,r.activity());}case "/dsa/employee-connection-graph"->{hr(u);employeeDepartmentGraph(q,s,r);}case "/dsa/graph"->{
   hr(u);
   Map<String,String> parameters=queryParameters(q.getQuery(),Set.of("ids","start","all"));
   if(parameters.containsKey("ids")&&parameters.containsKey("start"))throw new IllegalArgumentException("Choose either selected graph IDs or a BFS starting ID.");
   boolean showAll=parameters.containsKey("all")||parameters.containsKey("ids");
   List<Employee> vertices=showAll?r.employees().stream().sorted(Comparator.comparing(Employee::id,String.CASE_INSENSITIVE_ORDER)).toList():EmployeeGraph.sampleEmployeeVertices(r.employees());
    EmployeeGraph fullGraph=EmployeeGraph.sampleEmployeeConnections(vertices),graph=fullGraph;
    Map<String,String> canonical=new TreeMap<>(String.CASE_INSENSITIVE_ORDER);fullGraph.adjacency().keySet().forEach(id->canonical.put(id,id));
   if(parameters.containsKey("ids")){
    String rawIds=parameters.get("ids");if(rawIds.isBlank())throw new IllegalArgumentException("Enter at least one employee ID.");
    Set<String> selectedIds=new LinkedHashSet<>();
    for(String rawId:rawIds.split(",",-1)){String entered=rawId.trim();if(entered.isEmpty())throw new IllegalArgumentException("Employee IDs must be separated by commas without empty entries.");String id=canonical.get(entered);if(id==null)throw new IllegalArgumentException("Unknown employee ID: "+entered);selectedIds.add(id);}
    graph=fullGraph.inducedSubgraph(selectedIds);
   }
   Map<String,Map<String,String>> employeeDetails=new LinkedHashMap<>();
   for(Employee employee:vertices)if(graph.adjacency().containsKey(employee.id()))employeeDetails.put(employee.id(),Map.of("id",employee.id(),"name",employee.name()));
   Map<String,Object> result=new LinkedHashMap<>();result.put("adjacency",graph.adjacency());result.put("employees",employeeDetails);result.put("vertices",graph.adjacency().size());result.put("edges",graph.adjacency().values().stream().mapToInt(List::size).sum()/2);result.put("meaning","Sample undirected graph connections for demonstration only; not real reporting or collaboration relationships.");
    if(parameters.containsKey("start")){String entered=parameters.get("start").trim(),start=canonical.get(entered);if(start==null)throw new IllegalArgumentException("Unknown starting employee ID: "+entered);result.put("start",start);result.put("bfs",fullGraph.bfs(start));}
   Web.send(s,200,result);
  }default->Web.send(s,404,Map.of("error","Not found"));}}catch(SecurityException e){Web.send(s,403,Map.of("error","Forbidden"));}catch(NoSuchElementException e){Web.send(s,404,Map.of("error","Record not found"));}catch(IllegalArgumentException e){Web.send(s,400,Map.of("error",e.getMessage()));}catch(RuntimeException e){Web.send(s,500,Map.of("error","Request could not be completed"));}}
 private static void employeeDepartmentGraph(HttpRequest request,HttpResponse response,AppData repo)throws IOException{
  Map<String,String> parameters=queryParameters(request.getQuery(),Set.of("ids","start"));
  List<Employee> employees=repo.employees().stream().sorted(Comparator.comparing(Employee::id,String.CASE_INSENSITIVE_ORDER)).toList();
  Set<String> departmentSet=new TreeSet<>(String.CASE_INSENSITIVE_ORDER);departmentSet.addAll(repo.departments());employees.forEach(employee->departmentSet.add(employee.department()));
  List<String> departments=List.copyOf(departmentSet);
  EmployeeGraph fullGraph=EmployeeGraph.departmentMembershipGraph(employees,departments),graph=fullGraph;
  Map<String,String> canonical=new TreeMap<>(String.CASE_INSENSITIVE_ORDER);fullGraph.vertices().forEach(vertex->canonical.put(vertex,vertex));
  if(parameters.containsKey("ids")){
   String rawIds=parameters.get("ids");if(rawIds.isBlank())throw new IllegalArgumentException("Enter at least one employee ID.");
   Set<String> selectedEmployees=new LinkedHashSet<>();
   for(String rawId:rawIds.split(",",-1)){String entered=rawId.trim();if(entered.isEmpty())throw new IllegalArgumentException("Employee IDs must be separated by commas without empty entries.");String id=canonical.get(entered);if(id==null||employees.stream().noneMatch(employee->employee.id().equals(id)))throw new IllegalArgumentException("Unknown employee ID: "+entered);selectedEmployees.add(id);}
   Set<String> selectedVertices=new LinkedHashSet<>(departments);selectedVertices.addAll(selectedEmployees);graph=fullGraph.inducedSubgraph(selectedVertices);
   employees=employees.stream().filter(employee->selectedEmployees.contains(employee.id())).toList();
  }
  Map<String,Map<String,String>> employeeDetails=new LinkedHashMap<>();for(Employee employee:employees)employeeDetails.put(employee.id(),Map.of("id",employee.id(),"name",employee.name(),"department",employee.department()));
  List<Map<String,String>> edgeList=new ArrayList<>();Map<String,List<String>> adjacency=graph.adjacency();
  for(Employee employee:employees){String department=adjacency.getOrDefault(employee.id(),List.of()).stream().filter(vertex->departments.stream().anyMatch(name->name.equalsIgnoreCase(vertex))).findFirst().orElse(null);if(department!=null)edgeList.add(Map.of("employeeId",employee.id(),"department",department));}
  List<String> vertices=graph.vertices();List<Map<String,Object>> membershipMatrix=new ArrayList<>();
  for(Employee employee:employees){List<Integer> memberships=departments.stream().map(department->adjacency.getOrDefault(employee.id(),List.of()).contains(department)?1:0).toList();membershipMatrix.add(Map.of("employeeId",employee.id(),"employeeName",employee.name(),"values",memberships));}
  Map<String,Object> result=new LinkedHashMap<>();
  result.put("adjacency",adjacency);result.put("employees",employeeDetails);result.put("departments",departments);result.put("vertices",vertices);result.put("matrixLabels",vertices);result.put("adjacencyMatrix",graph.adjacencyMatrix());result.put("membershipMatrix",membershipMatrix);result.put("edgeList",edgeList);result.put("employeeCount",employees.size());result.put("departmentCount",departments.size());result.put("edgeCount",edgeList.size());
  if(parameters.containsKey("start")){String entered=parameters.get("start").trim(),start=canonical.get(entered);if(start==null||!adjacency.containsKey(start))throw new IllegalArgumentException("Unknown starting graph vertex: "+entered);result.put("start",start);result.put("bfs",graph.bfs(start));}
  Web.send(response,200,result);
 } public void post(HttpRequest q,HttpResponse s)throws IOException{String p=path(q);Web.UserSession u=Web.user(q);AppData r=App.repo();try{
  if(specialPost(p,u,r,q,s))return;JsonNode n=Web.body(q);switch(p){case "/employees"->{hr(u);Employee e=employee(n);r.changeEmployees(es->{if(es.stream().anyMatch(x->x.id().equalsIgnoreCase(e.id())))throw new IllegalArgumentException("Employee ID already exists");es.add(e);return null;});App.log(r,u.username(),"EMPLOYEE_CREATED",e.id());Web.send(s,201,e);}case "/requests"->{Employee own=owned(r,u);String type=Web.str(n,"type"),details=Web.str(n,"details");if(type.length()>60||details.length()>2000)throw new IllegalArgumentException("Request is too long");String leaveFrom=null,leaveTo=null;if(type.equalsIgnoreCase("Leave")){leaveFrom=Web.str(n,"leaveFrom");leaveTo=Web.str(n,"leaveTo");}EmployeeRequest x=new EmployeeRequest(UUID.randomUUID().toString(),own.id(),type,details,"PENDING",u.username(),Instant.now(),null,null,null,leaveFrom,leaveTo);r.submitRequest(x);App.log(r,u.username(),"REQUEST_SUBMITTED",x.id());Web.send(s,201,x);}case "/requests/decision"->{hr(u);String id=Web.str(n,"id"),decision=Web.str(n,"decision");if(!decision.equals("APPROVED")&&!decision.equals("REJECTED"))throw new IllegalArgumentException("Decision must be APPROVED or REJECTED");String note=n.hasNonNull("note")?n.get("note").asText():"";EmployeeRequest target=r.requests().stream().filter(x->x.id().equals(id)).findFirst().orElse(null);if(target==null){Web.send(s,404,Map.of("error","Request not found"));return;}if(target.type().equalsIgnoreCase("Leave")){try{r.processLeaveRequest(id,decision,u.username(),note);}catch(java.util.NoSuchElementException error){Web.send(s,404,Map.of("error",error.getMessage()));return;}catch(IOException error){Web.send(s,500,Map.of("error","Leave decision could not be saved; the application remains pending."));return;}}else{boolean changed=r.changeRequests(a->{for(int i=0;i<a.size();i++){var x=a.get(i);if(x.id().equals(id)){if(!x.status().equals("PENDING"))throw new IllegalArgumentException("Request already decided");EmployeeRequest firstPending=a.stream().filter(pending->pending.status().equals("PENDING")).findFirst().orElse(null);if(firstPending!=null&&!firstPending.id().equals(x.id()))throw new IllegalArgumentException("Review pending employee requests in submission order.");a.set(i,new EmployeeRequest(x.id(),x.employeeId(),x.type(),x.details(),decision,x.createdBy(),x.createdAt(),u.username(),Instant.now(),note,x.leaveFrom(),x.leaveTo()));return true;}}return false;});if(!changed){Web.send(s,404,Map.of("error","Request not found"));return;}}App.log(r,u.username(),"REQUEST_"+decision,id);Web.send(s,200,Map.of("ok",true));}default->Web.send(s,404,Map.of("error","Not found"));}}catch(SecurityException e){Web.send(s,403,Map.of("error","Forbidden"));}catch(IllegalArgumentException e){Web.send(s,400,Map.of("error",e.getMessage()));}catch(RuntimeException e){Web.send(s,500,Map.of("error","Request could not be completed"));}}
 public void put(HttpRequest q,HttpResponse s)throws IOException{Web.UserSession u=Web.user(q);String id=path(q);AppData repo=App.repo();try{if(specialDepartmentPut(id,u,repo,q,s))return;if(id.equals("/profile")){if(u==null||!u.role().equals("EMPLOYEE")){Web.send(s,403,Map.of("error","Forbidden"));return;}var n=Web.body(q);String name=Web.str(n,"name").strip(),email=Web.str(n,"email").strip(),phone=Web.str(n,"phone").strip();Employee own=owned(repo,u);if(repo.employees().stream().anyMatch(e->!e.id().equals(own.id())&&e.email().equalsIgnoreCase(email)))throw new IllegalArgumentException("Email address is already in use.");Employee updated=new Employee(own.id(),name,own.department(),own.designation(),email,phone,own.joiningDate(),own.status(),own.salary());repo.changeEmployees(es->{for(int i=0;i<es.size();i++)if(es.get(i).id().equalsIgnoreCase(own.id())){es.set(i,updated);return null;}throw new NoSuchElementException();});App.log(repo,u.username(),"EMPLOYEE_PROFILE_UPDATED",own.id());Web.send(s,200,Map.of("employee",updated));return;}if(!privileged(u)){Web.send(s,403,Map.of("error","Forbidden"));return;}if(!id.startsWith("/employees/")||id.substring("/employees/".length()).contains("/")){Web.send(s,404,Map.of("error","Not found"));return;}String employeeId=id.substring("/employees/".length());Employee e=employee(Web.body(q));if(!e.id().equalsIgnoreCase(employeeId))throw new IllegalArgumentException("Employee ID cannot be changed");boolean ok=repo.changeEmployees(a->{for(int i=0;i<a.size();i++)if(a.get(i).id().equalsIgnoreCase(employeeId)){if(a.stream().anyMatch(other->!other.id().equalsIgnoreCase(employeeId)&&other.email().equalsIgnoreCase(e.email())))throw new IllegalArgumentException("Employee email address already exists");a.set(i,e);return true;}return false;});if(!ok){Web.send(s,404,Map.of("error","Record not found"));return;}App.log(repo,u.username(),"EMPLOYEE_UPDATED",employeeId);Web.send(s,200,e);}catch(NoSuchElementException ex){Web.send(s,404,Map.of("error","Record not found"));}catch(IllegalArgumentException ex){Web.send(s,400,Map.of("error",ex.getMessage()));}}
 public void delete(HttpRequest q,HttpResponse s)throws IOException{Web.UserSession u=Web.user(q);AppData r=App.repo();if(specialDepartmentDelete(path(q),u,r,s))return;if(u==null||!privileged(u)){Web.send(s,403,Map.of("error","Forbidden"));return;}String id=path(q).replaceFirst("^/employees/","");boolean removed;try{removed=r.deleteEmployeeIfUnreferenced(id);}catch(IllegalStateException ex){Web.send(s,409,Map.of("error",ex.getMessage()));return;}if(!removed){Web.send(s,404,Map.of("error","Record not found"));return;}App.log(r,u.username(),"EMPLOYEE_DELETED",id);Web.send(s,200,Map.of("ok",true));}
 private static boolean specialGet(String path,Web.UserSession user,AppData repo,HttpResponse response)throws IOException {
  if(path.equals("/dsa/workload-distribution")){hr(user);edu.college.employee.service.EmployeeWorkloadService.View view;try{view=App.employeeWorkloadService().view();}catch(IOException error){Web.send(response,500,Map.of("error",error.getMessage()==null?"Could not load workload storage.":error.getMessage()));return true;}Web.send(response,200,view);return true;}
  if(path.equals("/dsa/employee-binary-tree")){hr(user);Web.send(response,200,employeeBinaryTreeView(repo.employeeTree(),"",null));return true;}
  if(path.equals("/departments")){hr(user);Web.send(response,200,repo.departments());return true;}
  if(path.equals("/registration-requests")){hr(user);Web.send(response,200,repo.registrationRequests().stream().map(x->Map.of("id",x.id(),"username",x.username(),"employeeId",x.employeeId(),"name",x.name(),"email",x.email(),"phone",x.phone(),"status",x.status(),"createdAt",x.createdAt().toString())).toList());return true;}
  return false;
 }
 private static boolean specialPost(String path,Web.UserSession user,AppData repo,HttpRequest request,HttpResponse response)throws IOException {
  if(path.equals("/dsa/workload-distribution")){hr(user);var body=Web.body(request);String action=Web.str(body,"action");try{var service=App.employeeWorkloadService();if(action.equals("simulate")){Web.send(response,200,service.simulate());return true;}var result=switch(action){case "addTask"->service.addTask(Web.str(body,"taskName"),body.hasNonNull("description")?body.get("description").asText():"",Web.str(body,"difficulty"));case "removeTask"->service.removeTask(Web.str(body,"taskId"));case "allocate"->service.allocate();case "resetWorkload"->service.resetWorkload(Web.str(body,"employeeId"));default->throw new IllegalArgumentException("Choose addTask, removeTask, allocate, or resetWorkload.");};Web.send(response,200,result);}catch(IOException error){Web.send(response,500,Map.of("error",error.getMessage()==null?"Could not save workload data.":error.getMessage()));}return true;}
  if(path.equals("/dsa/employee-binary-tree")){hr(user);var body=Web.body(request);var tree=repo.employeeTree();String action=Web.str(body,"action"),id=body.hasNonNull("employeeId")?body.get("employeeId").asText():"";Employee result=null;String message;switch(action){case "insert"->{result=repo.insertEmployeeInTree(employee(body));message="Employee added to the Binary Tree and saved permanently.";}case "update"->{result=repo.updateEmployeeInTree(id,employee(body));message="Employee updated in the Binary Tree and saved permanently.";}case "delete"->{result=repo.deleteEmployeeFromTree(id);message="Employee deleted from the Binary Tree and saved permanently.";}case "search"->{result=repo.searchEmployeeInTree(id);message=result==null?"Employee ID was not found in the Binary Tree.":"Employee found in the Binary Tree.";}default->throw new IllegalArgumentException("Choose insert, update, search, or delete.");}Web.send(response,200,employeeBinaryTreeView(tree,message,result));return true;}
  if(path.equals("/password")){if(user==null||!user.role().equals("EMPLOYEE")){Web.send(response,403,Map.of("error","Forbidden"));return true;}var body=Web.body(request);String current=Web.str(body,"currentPassword"),next=Web.str(body,"newPassword");if(next.length()<12||next.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>72||next.chars().noneMatch(Character::isLowerCase)||next.chars().noneMatch(Character::isUpperCase)||next.chars().noneMatch(Character::isDigit)||next.chars().allMatch(Character::isLetterOrDigit))throw new IllegalArgumentException("Use 12+ characters with upper and lowercase letters, a number, and a symbol.");var existing=repo.users().stream().filter(x->x.username().equalsIgnoreCase(user.username())).findFirst().orElseThrow();if(!org.mindrot.jbcrypt.BCrypt.checkpw(current,existing.passwordHash())){Web.send(response,400,Map.of("error","Current password is incorrect."));return true;}String hash=org.mindrot.jbcrypt.BCrypt.hashpw(next,org.mindrot.jbcrypt.BCrypt.gensalt(12));repo.changeUsers(users->{for(int i=0;i<users.size();i++)if(users.get(i).username().equalsIgnoreCase(user.username())){users.set(i,new User(existing.username(),hash,existing.role(),existing.employeeId(),existing.active()));return null;}throw new NoSuchElementException();});App.log(repo,user.username(),"PASSWORD_CHANGED","account");LocalSession currentSession=request.getSession(false);LocalSession.invalidateOtherSessions(user.username(),currentSession);request.changeSessionId();request.writeSessionCookie(response);Web.send(response,200,Map.of("ok",true));return true;}
  if(path.equals("/departments")){hr(user);String name=Web.str(Web.body(request),"name").strip();if(name.isBlank()||name.length()>80)throw new IllegalArgumentException("Department name must be 1-80 characters.");if(repo.departments().stream().anyMatch(x->x.equalsIgnoreCase(name)))throw new IllegalArgumentException("Department already exists.");repo.changeDepartments(names->{names.add(name);return null;});App.log(repo,user.username(),"DEPARTMENT_CREATED",name);Web.send(response,201,Map.of("name",name));return true;}
  if(path.equals("/registration-requests/decision")){hr(user);var body=Web.body(request);String id=Web.str(body,"id"),decision=Web.str(body,"decision");if(!decision.equals("APPROVED")&&!decision.equals("REJECTED"))throw new IllegalArgumentException("Decision must be APPROVED or REJECTED.");repo.changeRegistrationRequests(requests->{for(int i=0;i<requests.size();i++){var x=requests.get(i);if(x.id().equals(id)){if(!x.status().equals("PENDING"))throw new IllegalArgumentException("Registration request already reviewed.");if(decision.equals("APPROVED")){if(repo.employees().stream().noneMatch(e->e.id().equalsIgnoreCase(x.employeeId())&&e.status().equals("ACTIVE")))throw new IllegalArgumentException("Employee record must be active before account approval.");repo.changeUsers(users->{if(users.stream().anyMatch(a->a.username().equalsIgnoreCase(x.username())||a.role().equals("EMPLOYEE")&&x.employeeId().equalsIgnoreCase(a.employeeId())))throw new IllegalArgumentException("An account already exists for this request.");users.add(new User(x.username(),x.passwordHash(),"EMPLOYEE",x.employeeId()));return null;});}var next=new RegistrationRequest(x.id(),x.username(),x.passwordHash(),x.employeeId(),x.name(),x.email(),x.phone(),decision,x.createdAt(),user.username(),Instant.now());requests.set(i,next);return null;}}throw new NoSuchElementException("Registration request not found.");});App.log(repo,user.username(),"EMPLOYEE_REGISTRATION_"+decision,id);Web.send(response,200,Map.of("ok",true));return true;}
  return false;
 }
 private static boolean specialDepartmentPut(String id,Web.UserSession user,AppData repo,HttpRequest request,HttpResponse response)throws IOException {
  if(!id.startsWith("/departments/"))return false;if(!privileged(user)){Web.send(response,403,Map.of("error","Forbidden"));return true;}String previous=java.net.URLDecoder.decode(id.substring("/departments/".length()),java.nio.charset.StandardCharsets.UTF_8);String next=Web.str(Web.body(request),"name").strip();if(next.isBlank()||next.length()>80)throw new IllegalArgumentException("Department name must be 1-80 characters.");if(repo.departments().stream().noneMatch(x->x.equalsIgnoreCase(previous)))throw new NoSuchElementException("Department not found.");if(repo.departments().stream().anyMatch(x->!x.equalsIgnoreCase(previous)&&x.equalsIgnoreCase(next)))throw new IllegalArgumentException("Department already exists.");repo.changeEmployees(es->{for(int i=0;i<es.size();i++){Employee e=es.get(i);if(e.department().equalsIgnoreCase(previous))es.set(i,new Employee(e.id(),e.name(),next,e.designation(),e.email(),e.phone(),e.joiningDate(),e.status(),e.salary()));}return null;});repo.changeDepartments(names->{names.removeIf(x->x.equalsIgnoreCase(previous));names.add(next);return null;});App.log(repo,user.username(),"DEPARTMENT_RENAMED",previous+" -> "+next);Web.send(response,200,Map.of("name",next));return true;
 }
 private static boolean specialDepartmentDelete(String id,Web.UserSession user,AppData repo,HttpResponse response)throws IOException {
  if(!id.startsWith("/departments/"))return false;if(!privileged(user)){Web.send(response,403,Map.of("error","Forbidden"));return true;}String name=java.net.URLDecoder.decode(id.substring("/departments/".length()),java.nio.charset.StandardCharsets.UTF_8);if(repo.employees().stream().anyMatch(e->e.department().equalsIgnoreCase(name))){Web.send(response,409,Map.of("error","Move employees to another department before deleting this department."));return true;}boolean removed=repo.changeDepartments(names->names.removeIf(x->x.equalsIgnoreCase(name)));if(!removed){Web.send(response,404,Map.of("error","Department not found."));return true;}App.log(repo,user.username(),"DEPARTMENT_DELETED",name);Web.send(response,200,Map.of("ok",true));return true;
 }
 private static Map<String,Object> employeeBinaryTreeView(EmployeeBinaryTree tree,String message,Employee found){Map<String,Object> result=new LinkedHashMap<>();result.put("size",tree.size());result.put("storageFile","data/employee-tree.json");result.put("warning",tree.loadWarning());result.put("message",message);result.put("foundEmployee",found);result.put("traversals",Map.of("inorder",tree.inorder(),"preorder",tree.preorder(),"postorder",tree.postorder()));return result;}
 private static String path(HttpRequest q){return q.getRequestURI().substring(4);}private static BigDecimal money(String s){if(s.length()>24)throw new IllegalArgumentException("Monetary value is too large");BigDecimal n=new BigDecimal(s);if(Math.abs(n.scale())>2||n.precision()>16)throw new IllegalArgumentException("Use a monetary value with at most two decimal places");return n;}private static boolean privileged(Web.UserSession u){return u!=null&&(u.role().equals("ADMIN")||u.role().equals("HR"));}private static void hr(Web.UserSession u){if(!privileged(u))throw new SecurityException();}private static Employee owned(AppData r,Web.UserSession u){if(u==null||!u.role().equals("EMPLOYEE"))throw new SecurityException();return r.employees().stream().filter(e->e.id().equals(u.employeeId())).findFirst().orElseThrow(()->new SecurityException("Employee record not found"));}
 private static Employee employee(JsonNode n){return new Employee(Web.str(n,"id"),Web.str(n,"name"),Web.str(n,"department"),Web.str(n,"designation"),Web.str(n,"email"),Web.str(n,"phone"),LocalDate.parse(Web.str(n,"joiningDate")),Web.str(n,"status"),new BigDecimal(Web.str(n,"salary")));}static List<Employee> searchEmployees(List<Employee> employees,String search,String status,String algorithm,java.util.function.Function<String,Employee> bstSearch){if(!Set.of("linear","binary","bst").contains(algorithm))throw new IllegalArgumentException("Unsupported employee search algorithm.");if(search==null||search.isBlank()){String requiredStatus=status==null?"":status.strip();return employees.stream().filter(employee->requiredStatus.isEmpty()||employee.status().equalsIgnoreCase(requiredStatus)).toList();}return switch(algorithm){case "linear"->EmployeeAlgorithms.linearSearch(employees,search,status);case "binary"->EmployeeAlgorithms.binarySearch(employees,search,status);case "bst"->{Employee match=bstSearch.apply(search.strip());yield match==null||status!=null&&!status.isBlank()&&!match.status().equalsIgnoreCase(status)?List.of():List.of(match);}default->throw new IllegalArgumentException("Unsupported employee search algorithm.");};}static Map<String,String> employeeSortQuery(String raw){Map<String,String> values=new HashMap<>();if(raw==null||raw.isEmpty())return values;for(String part:raw.split("&",-1)){String[] pair=part.split("=",2);String key=java.net.URLDecoder.decode(pair[0],java.nio.charset.StandardCharsets.UTF_8);if(pair.length!=2||!Set.of("sortBy","direction","search","status","searchAlgorithm").contains(key)||values.putIfAbsent(key,java.net.URLDecoder.decode(pair[1],java.nio.charset.StandardCharsets.UTF_8))!=null)throw new IllegalArgumentException("Malformed employee list parameters.");}return values;}static Map<String,String> queryParameters(String raw,Set<String> allowed){Map<String,String> values=new HashMap<>();if(raw==null||raw.isEmpty())return values;for(String part:raw.split("&",-1)){String[] pair=part.split("=",2);String key=java.net.URLDecoder.decode(pair[0],java.nio.charset.StandardCharsets.UTF_8);if(pair.length!=2||!allowed.contains(key)||values.putIfAbsent(key,java.net.URLDecoder.decode(pair[1],java.nio.charset.StandardCharsets.UTF_8))!=null)throw new IllegalArgumentException("Malformed query parameters");}return Map.copyOf(values);}}





